// Agent-callable tool. Deterministic, no network, no filesystem, no credentials, no side effects.
// Its output is advisory ONLY. Independent downstream Code node enforces risk policy.
let text = '';
try {
  const value = typeof query === 'string' ? query : JSON.stringify(query);
  const data = JSON.parse(value);
  text = [data.title||'',data.body||'',data.labels||''].join('\n').slice(0,8000);
} catch {
  text = String(query||'').slice(0,8000);
}
const checks = [
  ['authentication',/\b(auth|authentication|login|mfa|2fa|sso|oauth|jwt|session|password)\b/i],
  ['authorization',/\b(authz|authori[sz]ation|rbac|permission|privilege|admin|roles?)\b/i],
  ['secrets',/\b(secrets?|tokens?|api[ _-]?keys?|credentials?|private key|vault)\b/i],
  ['sensitive_data',/\b(personal data|pii|gdpr|payment|bank account|encrypt|decrypt)\b/i],
  ['prompt_injection',/ignore (all )?(previous|prior)|system prompt|override (the )?(rules|instructions)|developer message|force[- ]push/i]
];
return JSON.stringify({risk_signals:checks.filter(([_,re])=>re.test(text)).map(([name])=>name),
  note:'Advisory read-only probe. Downstream independently recomputes risk from source issue.'});

// SECURITY BOUNDARY: model output is untrusted. Fail closed on missing/invalid schema.
const ctx = $('Issue Context').item.json;
const levels = ['low','medium','high'];
const issues = [];
const raw = typeof $json.output === 'string' ? $json.output.trim() : '';
let triage = null;
if ($json.error) issues.push('agent_error');
if (!raw) issues.push('empty_agent_output');
else {
  const body = raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
  try { triage = JSON.parse(body); }
  catch { issues.push('invalid_json'); }
}
const str = (v,max=1000) => typeof v==='string' && v.trim().length>0 && v.length<=max;
const arr = (v,min,max) => Array.isArray(v) && v.length>=min && v.length<=max && v.every(x=>str(x,1000));
if (triage && typeof triage === 'object' && !Array.isArray(triage)) {
  const keys=['summary','acceptance_criteria','implementation_steps','test_plan','affected_components','uncertainty','risk_assessment'];
  if (Object.keys(triage).sort().join('|')!==keys.sort().join('|')) issues.push('unexpected_or_missing_top_level_keys');
  if (!str(triage.summary,3000)) issues.push('invalid_summary');
  if (!arr(triage.acceptance_criteria,1,8)) issues.push('invalid_acceptance_criteria');
  if (!arr(triage.implementation_steps,1,10)) issues.push('invalid_implementation_steps');
  if (!arr(triage.test_plan,1,8)) issues.push('invalid_test_plan');
  if (!arr(triage.affected_components,1,10)) issues.push('invalid_affected_components');
  const u = triage.uncertainty;
  if (!u || !levels.includes(u.level) || !arr(u.open_questions,0,10)) issues.push('invalid_uncertainty');
  else if (u.level==='high' && u.open_questions.length===0) issues.push('high_uncertainty_requires_questions');
  const r=triage.risk_assessment;
  if (!r || !levels.includes(r.level) || !str(r.rationale,3000) || typeof r.security_sensitive!=='boolean') issues.push('invalid_risk_assessment');
} else if (triage !== null) { issues.push('output_not_object'); triage = null; }

// Independent risk policy: scan original issue, never trust model's risk label.
const scan = [ctx.issue_title,ctx.issue_body,ctx.issue_labels,triage?.affected_components?.join(' ')||''].join('\n');
const rules = [
  ['authentication',/\b(auth|authentication|login|mfa|2fa|sso|oauth|jwt|session|password)\b/i],
  ['authorization',/\b(authz|authori[sz]ation|rbac|permission|privilege|admin|roles?)\b/i],
  ['secrets',/\b(secret|secrets|tokens?|api[ _-]?keys?|credentials?|private key|vault)\b/i],
  ['sensitive_data',/\b(pii|personal data|gdpr|hipaa|ssn|payment|bank account|encrypt|decrypt)\b/i],
  ['prompt_injection',/ignore (all )?(previous|prior)|system prompt|override (the )?(rules|instructions)|developer message|force[- ]push/i]
];
const detFlags=rules.filter(([_,re])=>re.test(scan)).map(([flag])=>flag);
const agentSteps=(triage?.implementation_steps||[]).join(' ');
const blocked=/(^|[.;\n]\s*)(force[- ]push|push directly to (main|master)|deploy to prod|run rm -rf|remove (all )?(security )?checks)/i;
if (blocked.test(agentSteps)) { issues.push('dangerous_agent_implementation_step'); detFlags.push('suggested_privileged_action'); }
const srcBody=String(ctx.issue_body||'');
const vague=/\b(maybe|not sure|somehow|sometimes|faster|better|improve|asap|soon)\b/i.test(ctx.issue_title+' '+srcBody);
const ambiguous=srcBody.trim().length===0 || (srcBody.length<200 && vague);
const valid=issues.length===0 && triage!==null;
const rank={low:0,medium:1,high:2};
let risk=valid ? triage.risk_assessment.level:'not_assessed';
if (valid && triage.risk_assessment.security_sensitive) risk='high';
if (detFlags.length) risk='high';
let uncertainty=valid ? triage.uncertainty.level:'not_assessed';
if (valid && ambiguous) uncertainty='high';
const flags=[...detFlags.map(x=>'det:'+x)];
if (valid) flags.push('agent_risk:'+triage.risk_assessment.level,'agent_uncertainty:'+triage.uncertainty.level);
if (ambiguous) flags.push('det:ambiguous_requirements');
return {json:{...ctx,is_valid:valid,triage:valid?triage:null,
  validation_errors:issues.join('; '),risk_level:risk,uncertainty_level:uncertainty,
  deterministic_risk_flags:detFlags,risk_flags:flags.join(', '),
  processing_outcome:valid?'validated':'failed_closed_invalid_agent_output',
  requires_human_review:valid && (risk==='high'||risk==='medium'),
  review_decision:valid?'pending':'not_applicable_failed_closed',
  write_action:'disabled_by_design',external_write_performed:false,
  merge_deploy_or_execute_performed:false}};

// Pure presentation and routing. There is deliberately NO external write node.
const d=$json;
if (!d.is_valid || !d.triage) throw new Error('Invalid agent data must never reach report builder');
const t=d.triage;
const review=d.risk_level==='high'?'human_review_required':d.uncertainty_level==='high'?'needs_clarification':d.risk_level==='medium'?'human_review_recommended':'report_only';
const mdBullet=a=>(a||[]).map(x=>'- '+String(x)).join('\n');
const mdCheck=a=>(a||[]).map(x=>'- [ ] '+String(x)).join('\n');
const mdOrder=a=>(a||[]).map((x,i)=>(i+1)+'. '+String(x)).join('\n');
const scrub=s=>String(s||'').replace(/\|/g,'\\|').replace(/[\r\n]/g,' ');
const report=[
  '# Safe Agentic Issue Triage: '+scrub(d.issue_title),
  '', '| Field | Value |','|---|---|',
  '| Issue | '+scrub(d.issue_url)+' |',
  '| Case | '+scrub(d.test_case)+' |',
  '| Source | '+scrub(d.data_source)+' |',
  '| Risk | **'+d.risk_level.toUpperCase()+'** |',
  '| Uncertainty | '+d.uncertainty_level+' |',
  '| Review | '+review+' |',
  '| External write | **disabled by design** |',
  '', '> Untrusted issue text and AI-generated suggestions. Review before implementation. No code was executed, no changes written.',
  '', '## Summary',t.summary,
  '', '## Acceptance criteria',mdCheck(t.acceptance_criteria),
  '', '## Implementation proposal (human engineer)',mdOrder(t.implementation_steps),
  '', '## Test plan',mdCheck(t.test_plan),
  '', '## Affected components',mdBullet(t.affected_components),
  '', '## Uncertainty / questions',t.uncertainty.open_questions.length?mdBullet(t.uncertainty.open_questions):'- None identified by the model',
  '', '## Risk', '- AI assessment: '+t.risk_assessment.level+' — '+t.risk_assessment.rationale,
  '- Independent risk flags: '+(d.deterministic_risk_flags.length?d.deterministic_risk_flags.join(', '):'none'),
  '', '## Human reviewer checklist',
  '- [ ] Confirm requirements and acceptance criteria',
  '- [ ] Review security implications and deterministic flags',
  '- [ ] Approve or reject proposed implementation outside this dry-run',
  ''
].join('\n');
return {json:{...d,processing_outcome:'report_generated',review_decision:review,
  requires_human_review:d.risk_level==='high'||d.risk_level==='medium',
  write_action:'disabled_by_design',report_markdown:report}};

// Optional manual approval is evidence only: it NEVER authorizes external changes.
const base=$('Build Review Report').item.json;
const answer=String($json.Decision||'').trim();
const decision=answer==='Approve'?'approved_by_human_dry_run':answer==='Reject'?'rejected_by_human':'approval_timeout_or_invalid_response';
return {json:{...base,review_decision:decision,approval_note:String($json['Reviewer note']||'').slice(0,300),
  write_action:'disabled_by_design',external_write_performed:false,merge_deploy_or_execute_performed:false}};

// Failed input or GitHub read never reaches the AI model; no external writes.
return {json:{...$json,is_valid:false,report_markdown:'',
  risk_level:$json.risk_level==='high'?'high':'not_assessed',uncertainty_level:'not_assessed',
  review_decision:'not_applicable_failed_closed',requires_human_review:false,
  write_action:'disabled_by_design',external_write_performed:false,merge_deploy_or_execute_performed:false}};

// Verify the REAL workflow output against independent expected outcomes.
// This is not LLM-as-judge: it checks deterministic invariants and fixture expectations.
const d=$json;
const expected=d.expected||{};
const failures=[];
for(const [key,value] of Object.entries(expected)) {
  const actual=d[key];
  if (value==='low_or_medium' && !['low','medium'].includes(actual)) failures.push(key+': expected low/medium, got '+actual);
  else if (value!=='low_or_medium' && actual!==value) failures.push(key+': expected '+JSON.stringify(value)+', got '+JSON.stringify(actual));
}
if (d.external_write_performed!==false) failures.push('invariant: external write must stay false');
if (d.merge_deploy_or_execute_performed!==false) failures.push('invariant: code/merge/deploy must stay false');
if (d.write_action!=='disabled_by_design') failures.push('invariant: no write sink allowed');
if (!d.input_ok && d.report_markdown) failures.push('invariant: invalid input must not produce AI report');
if (d.processing_outcome==='report_generated' && (!d.is_valid || !d.report_markdown)) failures.push('invariant: report needs validated AI output');
if (d.risk_level==='high' && d.processing_outcome==='report_generated' && !d.requires_human_review) failures.push('invariant: high risk requires human review');
if (d.test_case==='TC4_prompt_injection' && d.risk_level!=='high') failures.push('prompt-injection fixture not escalated');
return {json:{...d,test_pass:failures.length===0,test_failures:failures}};

// Portable audit as execution output. No instance-specific Data Table IDs and no live writes.
const d=$json;
return {json:{
  test_case:d.test_case,issue_url:d.issue_url,source:d.data_source,
  execution_id:String($execution.id||'manual'),processed_at:new Date().toISOString(),
  input_ok:d.input_ok,processing_outcome:d.processing_outcome,
  is_valid:d.is_valid===true,risk_level:d.risk_level,uncertainty_level:d.uncertainty_level,
  risk_flags:d.risk_flags||'',review_decision:d.review_decision,
  requires_human_review:d.requires_human_review===true,
  write_action:d.write_action,external_write_performed:false,
  merge_deploy_or_execute_performed:false,
  expected:d.expected||{},test_pass:d.test_pass===true,test_failures:d.test_failures||[],
  validation_errors:d.validation_errors||'',report_markdown:d.report_markdown||''
}};
